import json,re
rows={r['_step']:r for r in (json.loads(l) for l in open('wandb-history.jsonl'))}
# pull step 60 from train.log console line
for line in open('train.log'):
    if 'step:60 -' in line:
        for kv in re.findall(r'([\w/\.\-@]+):([-0-9\.e+naif]+)', line):
            k,v=kv
            try: rows.setdefault(60,{})[k]=float(v)
            except ValueError: rows[60][k]=v
def g(s,k): return rows.get(s,{}).get(k)
def f(s,k,n=4):
    v=g(s,k)
    return 'None' if v is None else (f'{v:.{n}g}' if isinstance(v,float) else str(v))
keys=[('rollout_corr/rollout_ppl','rollout_ppl'),('rollout_corr/training_ppl','training_ppl'),
      ('rollout_corr/training_log_ppl','training_log_ppl'),
      ('training/rollout_actor_probs_pearson_corr','pearson_corr'),
      ('training/rollout_probs_diff_mean','probs_diff_mean'),
      ('actor/entropy','entropy'),('actor/kl_loss','kl_loss'),('actor/grad_norm','grad_norm'),
      ('critic/score/mean','score_mean'),('val-core/openai/gsm8k/acc/mean@1','val_acc')]
steps=[1,20,40,58,60]
print('metric'.ljust(18)+''.join(f'step{s}'.rjust(14) for s in steps))
for k,label in keys:
    print(label.ljust(18)+''.join(f(s,k).rjust(14) for s in steps))
gn=[(s,r['actor/grad_norm']) for s,r in rows.items() if 'actor/grad_norm' in r]
print('\ngrad_norm peak:', max(gn,key=lambda t:t[1]))
print('step60 present:', 60 in rows)
